346	\begin{theorem}[Closeness of inner products]\label{prop:closeness-of-ip}
347		\lean{MIPStarRE.LDT.Preliminaries.closenessOfIP, MIPStarRE.LDT.Preliminaries.closenessOfIPAdjoint}
348		\leanok
349		\uses{def:approx_delta}
350		Let $\{A^x_a\}$, $\{B^x_a\}$, and $\{C^x_{a,b}\}$ be matrices. Suppose that $A^x_a \approx_\gamma B^x_a$ and that for all~$x$,
351		\[
352			\sum_a \Big(\sum_b C^x_{a,b}\Big) \Big(\sum_b C^x_{a,b}\Big)^\dagger \le I.
353		\]
354		Then
355		\begin{equation}
356			\E_{\bx} \sum_{a,b} \bra{\psi} C^{\bx}_{a,b} A^{\bx}_a  \ket{\psi} \approx_{\sqrt{\gamma}} \E_{\bx} \sum_{a,b} \bra{\psi} C^{\bx}_{a,b} B^{\bx}_a  \ket{\psi}. \label{eq:closeness3}
357		\end{equation}
358		Similarly, suppose that $(A^x_a)^\dagger \approx_\gamma (B^x_a)^\dagger$ and that for all~$x$,
359		\[
360			\sum_a \Big(\sum_b C^x_{a,b}\Big)^\dagger \Big(\sum_b C^x_{a,b}\Big) \le I.
420		\]
421	\end{theorem}
