\chapter{Preliminaries}
\label{chap:preliminaries}
% Paper label sec:prelims kept for cross-reference fidelity; resolves to chapter number.
\label{sec:prelims}

\section{Polynomials and measurements}

For complex numbers $\alpha,\beta \in \C$, write $\alpha \approx_\eps \beta$ when $|\alpha-\beta|\le \eps$. In particular,
\begin{equation}\label{eq:triangle-inequality-for-numbers}
	\text{if $\alpha \approx_{\eps} \beta$ and $\beta \approx_{\delta} \gamma$, then $\alpha \approx_{\eps+\delta}\gamma$.}
\end{equation}

Fix a prime power $q=p^t$. Write $\omega=e^{2\pi i/p}$, and let $\tr:\F_q\to\F_p$ denote the finite-field trace.

\begin{definition}[Finite field trace]\label{def:ff-trace}
	\lean{MIPStarRE.LDT.Preliminaries.ffTrace}
	\leanok
	The finite-field trace is the map $\tr:\F_q\to\F_p$ defined by
	\[
		\tr[x] = \sum_{\ell=0}^{t-1} x^{p^\ell}.
	\]
\end{definition}

\begin{lemma}\label{prop:fourier-fact-scalar}
	\lean{MIPStarRE.LDT.Preliminaries.fourier_fact_scalar}
	\leanok
	\uses{def:ff-trace}
	Let $a \in \F_q$. Then
	\begin{equation*}
		\E_{\bx \sim \F_q} \omega^{\tr[\bx \cdot a]}
		= \left\{\begin{array}{rl}
			1 & \text{if $a = 0$}, \\
			0 & \text{otherwise}.
		\end{array}\right.
	\end{equation*}
\end{lemma}
\begin{proof}
	\leanok
	If $a=0$, then $\tr[\bx\cdot a]=0$ for every $\bx$, so the average is $1$. If $a\neq 0$, choose $y \in \F_q$ such that $\tr[a\cdot y]\neq 0$, and set
	\[
		C=\E_{\bx \sim \F_q} \omega^{\tr[\bx \cdot a]}.
	\]
	Translation invariance of the uniform distribution gives
	\[
		C=\E_{\bx \sim \F_q} \omega^{\tr[(\bx+y)\cdot a]}
		= C \cdot \omega^{\tr[y\cdot a]}.
	\]
	Since $\omega^{\tr[y\cdot a]}\neq 1$, it follows that $C=0$.
\end{proof}

\begin{lemma}\label{prop:fourier-fact-vector}
	\lean{MIPStarRE.LDT.Preliminaries.fourier_fact_vector}
	\leanok
	\uses{def:ff-trace, prop:fourier-fact-scalar}
	Let $v \in \F_q^m$. Then
	\begin{equation*}
		\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
		= \left\{\begin{array}{rl}
			1 & \text{if $v = 0$}, \\
			0 & \text{otherwise}.
		\end{array}\right.
	\end{equation*}
\end{lemma}
\begin{proof}
	\leanok
	By linearity of the trace and independence of the coordinates,
	\[
		\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
		= \prod_{i=1}^m \E_{\bu_i \sim \F_q} \omega^{\tr[\bu_i \cdot v_i]}.
	\]
	Proposition~\ref{prop:fourier-fact-scalar} shows that the $i$-th factor is $1$ when $v_i=0$ and $0$ otherwise, so the product is $1$ exactly when $v=0$.
\end{proof}

\begin{lemma}[Fourier orthogonality for a finite index set]
\label{lem:fourier-fact-finite-index}
	\lean{MIPStarRE.LDT.Preliminaries.expect_ffChar_sum_mul}
	\lean{MIPStarRE.LDT.Preliminaries.sum_ffChar_sum_mul}
	\leanok
	\uses{def:ff-trace}
	This auxiliary lemma is a finite reindexing of
	Lemma~\ref{prop:fourier-fact-vector}, not a separate statement of the paper.
	Let $F$ be a finite field of prime characteristic $p$, with its canonical
	$\F_p$-algebra structure, and put $q=|F|$. Let $I$ be a finite index set,
	possibly empty, and let $v\in F^I$. Write
	$\chi(x)=\omega^{\tr[x]}$, where $\tr:F\to\F_p$ is the field trace.
	Then the uniform expectation and the unnormalized sum satisfy
	\[
		\E_{u\in F^I}\chi\Bigl(\sum_{i\in I}u_i v_i\Bigr)
		=\begin{cases}1&v=0,\\0&v\ne0,\end{cases}
		\qquad
		\sum_{u\in F^I}\chi\Bigl(\sum_{i\in I}u_i v_i\Bigr)
		=\begin{cases}q^{|I|}&v=0,\\0&v\ne0.\end{cases}
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{prop:fourier-fact-vector}
	Choose a bijection from $I$ to $\{0,\ldots,|I|-1\}$, interpreted as
	the empty set when $I$ is empty. Reindexing both vectors preserves their
	dot product, the uniform expectation, and the condition $v=0$.
	Lemma~\ref{prop:fourier-fact-vector} therefore gives the first identity.
	Multiplying by $|F^I|=q^{|I|}$ gives the second.
\end{proof}

\begin{definition}[Low individual degree polynomials]\label{def:polyfunc}
	\lean{MIPStarRE.LDT.Preliminaries.polyFunc, MIPStarRE.LDT.Polynomial}
	\leanok
	Let $\polyfunc{m}{q}{d}$ be the set of polynomials $g \in \F_q[x_1,\dots,x_m]$ whose degree in each variable is at most $d$, viewed as functions $\F_q^m \to \F_q$ via evaluation. (Over finite fields, distinct low-degree polynomials can induce the same function; we identify elements of $\polyfunc{m}{q}{d}$ with their polynomial representatives, not their functional equivalence classes.)
\end{definition}

\begin{remark}[Individual-degree convention]\label{rem:individual-degree-convention}
	Here, ``individual degree $d$'' means degree at most $d$ in each coordinate. In
	particular,
	\[
		\polyfunc{m}{q}{d} \subseteq \polyfunc{m}{q}{d+1}.
	\]
\end{remark}

\begin{lemma}[Schwartz--Zippel lemma~\cite{Sch80,Zip79}]\label{lem:schwartz-zippel-total-degree}
	\lean{MIPStarRE.LDT.Preliminaries.schwartzZippel_totalDegree}
	\leanok
	Let $g, h:\F_q^m \rightarrow \F_q$ be two distinct polynomials of total degree~$d$.
	Then
	\begin{equation*}
		\Prb_{\bx \sim \F_q^m}[g(\bx) = h(\bx)] \leq \frac{d}{q}.
	\lean{MIPStarRE.LDT.ConsRel}
	\leanok
	Let $\ket{\psi} \in \mathcal H_{\mathrm A} \ot \mathcal H_{\mathrm B}$. Let $A=\{A_a^x\}$ and $B=\{B_a^x\}$ be submeasurements with the same answer set, and let $\mathcal D$ be a distribution on the question set. We write
	\[
		A_a^x \ot I \simeq_\delta I \ot B_a^x
	\]
	when
	\begin{equation}\label{eq:no-big-Oh}
		\E_{x \sim \mathcal D} \sum_{a \ne b} \bra{\psi} A_a^x \ot B_b^x \ket{\psi} \le \delta.
	\end{equation}
\end{definition}

\begin{lemma}[Characterization of a good symmetric strategy]\label{lem:good-strategy-characterization}
	\lean{MIPStarRE.LDT.Preliminaries.goodStrategyCharacterization}
	\leanok
	\uses{def:good-strategy, def:simeq, prop:simeq-for-measurements}
	A symmetric projective strategy $(\psi,A,B,L)$ is $(\eps,\delta,\gamma)$-good if and only if the following hold on the relevant test distributions:
	\[
		A_a^u \ot I \simeq_\eps I \ot B^{\ell}_{[f(u)=a]},
		\qquad
		A_a^u \ot I \simeq_\delta I \ot A_a^u,
		\qquad
		A_a^u \ot I \simeq_\gamma I \ot L^{\ell}_{[f(u)=a]}.
	\]
\end{lemma}
\begin{proof}
	\leanok
	Each subtest accepts exactly when the two measurement outcomes agree. Because the relevant families are measurements, Lemma~\ref{prop:simeq-for-measurements} rewrites those acceptance probabilities as consistency bounds.
\end{proof}

\begin{lemma}[Consistency for measurements]\label{prop:simeq-for-measurements}
	\lean{MIPStarRE.LDT.Preliminaries.simeqForMeasurements}
	\leanok
	\uses{def:simeq}
	If $A=\{A_a^x\}$ and $B=\{B_a^x\}$ are measurements, then
	\[
		A_a^x \ot I \simeq_\delta I \ot B_a^x
		\qquad\text{if and only if}\qquad
		\E_x \sum_a \bra{\psi} A_a^x \ot B_a^x \ket{\psi} \ge 1-\delta.
	\]
\end{lemma}
\begin{proof}
	\leanok
	Expand the off-diagonal sum by writing $\sum_{a \ne b} A_a^x \ot B_b^x = \sum_b (I-A_b^x) \ot B_b^x$.
\end{proof}

\begin{definition}[State-dependent distance]\label{def:approx_delta}
	\lean{MIPStarRE.LDT.SDDRel}
	\leanok
	Let $\ket{\psi} \in \mathcal H$, let $A=\{A_a^x\}$ and $B=\{B_a^x\}$ be families of operators on $\mathcal H$, and let $\mathcal D$ be a distribution on the question set. We write
	\[
		A_a^x \approx_\delta B_a^x
	\]
	when
	\[
		\E_{x \sim \mathcal D} \sum_a \lVert (A_a^x-B_a^x)\ket{\psi} \rVert^2 \le \delta.
	\]
\end{definition}

In particular, if $A^x_a \ot I \simeq_{\eps} I \ot C^x_a$, the question is what hypothesis on $A$ and $B$ allows one to conclude that
\begin{equation}\label{eq:can-we-use-approx-delta-to-derive-this}
	B^x_a \ot I \simeq_{\eps} I \ot C^x_a.
\end{equation}

\begin{lemma}[Transferring consistency through state-dependent distance]\label{prop:triangle-sub}
	\lean{MIPStarRE.LDT.Preliminaries.triangleSub_heterogeneous}
	\leanok
	\uses{def:simeq, def:approx_delta, prop:simeq-for-measurements}
	Let $A=\{A_a^x\}$ and $B=\{B_a^x\}$ be measurements and let $C=\{C_a^x\}$ be a submeasurement. If $A_a^x \ot I \simeq_\delta I \ot C_a^x$ and $A_a^x \ot I \approx_\eps B_a^x \ot I$, then
	\[
		B_a^x \ot I \simeq_{\delta+\sqrt\eps} I \ot C_a^x.
	\]
\end{lemma}
\begin{proof}
	\leanok
	Rewrite the inconsistency with $C$ as total mass minus diagonal overlap. The total mass is unchanged because $A$ and $B$ are measurements, and the diagonal overlap changes by at most $\sqrt\eps$ by Cauchy--Schwarz.
\end{proof}

\begin{lemma}[Consistency implies state-dependent distance for measurements]\label{prop:simeq-to-approx}
	\lean{MIPStarRE.LDT.Preliminaries.simeqToApprox_heterogeneous, MIPStarRE.LDT.Preliminaries.approxToSimeq_heterogeneous}
	\leanok
	\uses{def:simeq, def:approx_delta, prop:simeq-for-measurements}
	If $A$ and $B$ are measurements and $A_a^x \ot I \simeq_\delta I \ot B_a^x$, then
	\[
		A_a^x \ot I \approx_{2\delta} I \ot B_a^x.
	\]
	If both measurements are projective, the converse also holds: if $A_a^x \ot I \approx_{2\delta} I \ot B_a^x$ then $A_a^x \ot I \simeq_\delta I \ot B_a^x$.
\end{lemma}
\begin{proof}
	\leanok
	Expand the squared norm of $(A_a^x \ot I - I \ot B_a^x)\ket{\psi}$ and use the diagonal-overlap formula from Lemma~\ref{prop:simeq-for-measurements}; projectivity turns the diagonal inequality into an equality, giving the converse.
\begin{proposition}[Formalization support: small-error linear-triangle branch]
\label{prop:main-formal-linear-triangle-small-error}
	\lean{MIPStarRE.LDT.Test.main_formal_linear_triangle_small_error_conclusion}
	\leanok
	\uses{def:main-formal-linear-triangle-errors, def:low-individual-degree-test,
		def:projective-strategy, def:polymeasurements, def:simeq}
	Let the projective strategy pass the low individual degree test with failure
	at most $\eps$.  If $k\ge400md$, $k>0$, and $T<1$, then there are projective
	polynomial measurements satisfying all three final consistency conclusions
	with error $\nu_{\mathrm{lin}}$.
\end{proposition}
\begin{proof}
	\leanok
	\uses{prop:main-formal-linear-triangle-projective-construction,
		lem:main-formal-linear-triangle-source-error-absorption}
	Use the projective measurements from the construction proposition and weaken
	their two explicit errors using the scalar absorption lemma.  Since $T<1$,
	the capped error equals $T$.
\end{proof}

\begin{theorem}[Formalization support: final theorem with the named capped error]
\label{thm:main-formal-linear-triangle-named-error}
	\lean{MIPStarRE.LDT.Test.main_formal_linear_triangle}
	\leanok
	\uses{def:main-formal-linear-triangle-errors, def:low-individual-degree-test,
		def:projective-strategy, def:polymeasurements, def:simeq}
	Under exactly the corrected hypotheses of Theorem~\ref{thm:main-formal},
	there are projective polynomial measurements satisfying its three
	consistency conclusions with error $\nu_{\mathrm{lin}}$.
\end{theorem}
\begin{proof}
	\leanok
	\uses{prop:main-formal-linear-triangle-saturated,
		prop:main-formal-linear-triangle-small-error}
	Split according to whether $T\ge1$.  Apply the saturated proposition in the
	first case and the small-error proposition in the second.
\end{proof}

\begin{theorem}[Complete-measurement linear-triangle bound]
\label{thm:main-formal-linear-triangle}
	\lean{MIPStarRE.LDT.Test.main_formal_linear_triangle_bound}
	\leanok
	\uses{def:low-individual-degree-test, def:projective-strategy,
		def:polymeasurements, def:simeq}
	Let $(\psi,A^{\mathrm A},B^{\mathrm A},L^{\mathrm A},
	A^{\mathrm B},B^{\mathrm B},L^{\mathrm B})$ be a projective strategy that
	passes the $(m,q,d)$ low individual degree test with probability at least
	$1-\eps$.  Let $k>0$ be an integer with $k\ge 400md$, and set
	\[
		T=10000 k^{1/4}m^{1/2}\left(
			\eps^{1/8192}+(d/q)^{1/8192}
			+e^{-k/(640000m^2)}\right),
		\qquad \nu_{\mathrm{lin}}=\min\{1,T\}.
	\]
	Then there are projective measurements
	$Q^{\mathrm A},Q^{\mathrm B}\in\polymeas{m}{q}{d}$ such that, on average
	over $u\sim\F_q^m$,
	\[
		A_a^{\mathrm A,u}\ot I\simeq_{\nu_{\mathrm{lin}}}
			I\ot Q^{\mathrm B}_{[g(u)=a]},
		\qquad
		I\ot A_a^{\mathrm B,u}\simeq_{\nu_{\mathrm{lin}}}
			Q^{\mathrm A}_{[g(u)=a]}\ot I,
	\]
	and
	\[
		Q_g^{\mathrm A}\ot I\simeq_{\nu_{\mathrm{lin}}}
			I\ot Q_g^{\mathrm B}.
	\]
	This is a Lean-only quantitative improvement obtained from the source proof.
	It does not replace or relabel Theorem~\ref{thm:main-formal}.
\end{theorem}
\begin{proof}
	\leanok
	\uses{thm:main-formal-linear-triangle-named-error,
		def:main-formal-linear-triangle-errors}
	Apply Theorem~\ref{thm:main-formal-linear-triangle-named-error} and substitute
	the displayed formulas for $T$ and $\nu_{\mathrm{lin}}$.
\end{proof}

\begin{lemma}[Formalization support: factor-ten comparison]
\label{lem:main-formal-linear-triangle-factor-ten}
	\lean{MIPStarRE.LDT.Test.ten_mul_mainFormalLinearTriangleRawError_le_mainFormalError}
	\leanok
	\uses{def:main-formal-linear-triangle-errors,
		prop:main-formal-explicit-baseline}
	Assume $q>0$, $k\ge1$, $m\ge1$, $0\le\eps\le1$, and $d\le q$.  Then
	\[
		10T\le \nu_{\mathrm{base}}.
	\]
\end{lemma}
\begin{proof}
	\leanok
	Use $8192\le40000$, $640000\le2560000$,
	$k^{1/4}\le k^2$, and $m^{1/2}\le m^4$ to compare the corresponding
	envelopes and prefactors.
\end{proof}

\begin{proposition}[Comparison of the two capped final errors]
\label{prop:main-formal-linear-triangle-comparison}
	\lean{MIPStarRE.LDT.Test.mainFormalLinearTriangleError_le_min_mainFormalError}
	\lean{MIPStarRE.LDT.Test.mainFormalLinearTriangleError_lt_min_mainFormalError}
	\leanok
	\uses{def:main-formal-linear-triangle-errors,
		prop:main-formal-explicit-baseline}
	Assume $\eps\ge0$ and $k>0$.  With $\nu_{\mathrm{lin}}$ as above and
	$\nu_{\mathrm{base}}$ from
	Proposition~\ref{prop:main-formal-explicit-baseline},
	\[
		\nu_{\mathrm{lin}}\le\min\{1,\nu_{\mathrm{base}}\}.
	\]
	If $\nu_{\mathrm{base}}<1$, then the inequality is strict.  More precisely,
	in that branch the formal scalar proof establishes
	$10T\le\nu_{\mathrm{base}}$; the exponential summand makes $T>0$.
\end{proposition}
\begin{proof}
	\leanok
	\uses{lem:main-formal-linear-triangle-factor-ten,
		lem:main-formal-linear-triangle-error-nonnegative}
	When the previous explicit error bound is at least one, both sides are capped
	by one.  Otherwise
	$0\le\eps\le1$ and $d/q\le1$.  Monotonicity of real powers and the exponential
	tail, together with $k^{1/4}\le k^2$ and $m^{1/2}\le m^4$, gives the stated
	factor-ten comparison.
\end{proof}

